content:
:root {
  --primary-color: #3b82f6;
  --primary-hover: #2563eb;
  --bg-color: #f8fafc;
  --card-bg: #ffffff;
  --text-main: #1e293b;
  --text-muted: #64748b;
  --border-color: #e2e8f0;
  --success-color: #10b981;
  --danger-color: #ef4444;
  --radius: 8px;
  --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  line-height: 1.5;
}

.app-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 2rem 1rem;
}

.header {
  margin-bottom: 2rem;
  text-align: center;
}

.title {
  font-size: 2rem;
  font-weight: 700;
  color: var(--text-main);
}

.card {
  background-color: var(--card-bg);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 1.5rem;
  margin-bottom: 2rem;
}

.chart-container {
  width: 100%;
  height: 400px;
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 1.5rem;
  margin-bottom: 2rem;
}

.stat-card {
  background-color: var(--card-bg);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 1.25rem;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.stat-card h3 {
  font-size: 0.875rem;
  color: var(--text-muted);
  font-weight: 600;
}

.stat-card .value {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text-main);
}

.table-container {
  overflow-x: auto;
}

.sales-table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
  font-size: 0.875rem;
}

.sales-table th,
.sales-table td {
  padding: 0.75rem 1rem;
  border-bottom: 1px solid var(--border-color);
}

.sales-table th {
  background-color: #f1f5f9;
  font-weight: 600;
  color: var(--text-muted);
}

.sales-table tr:hover {
  background-color: #f8fafc;
}

.form-group {
  margin-bottom: 1rem;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.form-group label {
  font-weight: 600;
  font-size: 0.875rem;
  color: var(--text-main);
}

.form-group input,
.form-group select {
  padding: 0.5rem 0.75rem;
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  font-size: 1rem;
  outline: none;
  transition: border-color 0.2s;
}

.form-group input:focus,
.form-group select:focus {
  border-color: var(--primary-color);
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.5rem 1rem;
  border-radius: var(--radius);
  font-weight: 600;
  font-size: 0.875rem;
  cursor: pointer;
  border: none;
  transition: background-color 0.2s;
}

.btn-primary {
  background-color: var(--primary-color);
  color: white;
}

.btn-primary:hover {
  background-color: var(--primary-hover);
}

@media (max-width: 768px) {
  .app-container {
    padding: 1rem 0.5rem;
  }

  .title {
    font-size: 1.5rem;
  }
}

export interface SalesData {
  month: string;
  sales: number;
  target: number;
}

export interface SalesChartProps {
  data: SalesData[];
}

import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';
import { SalesChartProps } from '../types';

export default function SalesChart({ data = [] }: SalesChartProps) {
  return (
    <div className="chart-container">
      <ResponsiveContainer width="100%" height="100%">
        <BarChart
          data={data}
          margin={{
            top: 20,
            right: 30,
            left: 20,
            bottom: 5,
          }}
        >
          <CartesianGrid strokeDasharray="3 3" />
          <XAxis dataKey="month" />
          <YAxis />
          <Tooltip />
          <Legend />
          <Bar dataKey="sales" name="売上実績 (万円)" fill="var(--primary-color)" />
          <Bar dataKey="target" name="目標金額 (万円)" fill="var(--success-color)" />
        </BarChart>
      </ResponsiveContainer>
    </div>
  );
}

import { useState } from 'react';
import SalesChart from './components/SalesChart';
import { SalesData } from './types';
import './index.css';

const initialData: SalesData[] = [
  { month: '1月', sales: 120, target: 150 },
  { month: '2月', sales: 135, target: 140 },
  { month: '3月', sales: 180, target: 170 },
  { month: '4月', sales: 150, target: 160 },
  { month: '5月', sales: 190, target: 180 },
  { month: '6月', sales: 210, target: 200 },
  { month: '7月', sales: 240, target: 220 },
  { month: '8月', sales: 200, target: 210 },
  { month: '9月', sales: 220, target: 220 },
  { month: '10月', sales: 250, target: 240 },
  { month: '11月', sales: 270, target: 260 },
  { month: '12月', sales: 300, target: 280 },
];

export default function App() {
  const [data, setData] = useState<SalesData[]>(initialData);
  const [selectedMonth, setSelectedMonth] = useState<string>('1月');
  const [salesInput, setSalesInput] = useState<string>('120');
  const [targetInput, setTargetInput] = useState<string>('150');

  // サマリー計算
  const totalSales = data.reduce((acc, cur) => acc + cur.sales, 0);
  const totalTarget = data.reduce((acc, cur) => acc + cur.target, 0);
  const achievementRate = totalTarget > 0 ? Math.round((totalSales / totalTarget) * 100) : 0;

  const handleMonthChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const month = e.target.value;
    setSelectedMonth(month);
    const found = data.find((d) => d.month === month);
    if (found) {
      setSalesInput(found.sales.toString());
      setTargetInput(found.target.toString());
    }
  };

  const handleUpdate = (e: React.FormEvent) => {
    e.preventDefault();
    const salesNum = Number(salesInput);
    const targetNum = Number(targetInput);

    if (isNaN(salesNum) || isNaN(targetNum)) return;

    setData((prev) =>
      prev.map((item) =>
        item.month === selectedMonth ? { ...item, sales: salesNum, target: targetNum } : item
      )
    );
  };

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">年間売上管理ダッシュボード</h1>
      </header>

      <div className="stats-grid">
        <div className="stat-card">
          <h3>年間総売上</h3>
          <div className="value">{totalSales.toLocaleString()} 万円</div>
        </div>
        <div className="stat-card">
          <h3>年間総目標</h3>
          <div className="value">{totalTarget.toLocaleString()} 万円</div>
        </div>
        <div className="stat-card">
          <h3>年間目標達成率</h3>
          <div className="value">{achievementRate}%</div>
        </div>
      </div>

      <div className="card">
        <h2 style={{ marginBottom: '1rem', fontSize: '1.25rem', fontWeight: 600 }}>
          売上と目標の推移
        </h2>
        <SalesChart data={data} />
      </div>

      <div className="card">
        <h2 style={{ marginBottom: '1rem', fontSize: '1.25rem', fontWeight: 600 }}>
          月別データ編集
        </h2>
        <form onSubmit={handleUpdate} style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '1rem', alignItems: 'end' }}>
          <div className="form-group">
            <label htmlFor="month-select">対象月</label>
            <select id="month-select" value={selectedMonth} onChange={handleMonthChange}>
              {data.map((item) => (
                <option key={item.month} value={item.month}>
                  {item.month}
                </option>
              ))}
            </select>
          </div>

          <div className="form-group">
            <label htmlFor="sales-input">売上実績 (万円)</label>
            <input
              id="sales-input"
              type="number"
              value={salesInput}
              onChange={(e) => setSalesInput(e.target.value)}
            />
          </div>

          <div className="form-group">
            <label htmlFor="target-input">目標金額 (万円)</label>
            <input
              id="target-input"
              type="number"
              value={targetInput}
              onChange={(e) => setTargetInput(e.target.value)}
            />
          </div>

          <div className="form-group">
            <button type="submit" className="btn btn-primary">
              更新する
            </button>
          </div>
        </form>
      </div>

      <div className="card">
        <h2 style={{ marginBottom: '1rem', fontSize: '1.25rem', fontWeight: 600 }}>
          月別売上・目標一覧
        </h2>
        <div className="table-container">
          <table className="sales-table">
            <thead>
              <tr>
                <th>月</th>
                <th>売上実績 (万円)</th>
                <th>目標金額 (万円)</th>
                <th>達成率</th>
              </tr>
            </thead>
            <tbody>
              {data.map((row) => {
                const rate = row.target > 0 ? Math.round((row.sales / row.target) * 100) : 0;
                return (
                  <tr key={row.month}>
                    <td>{row.month}</td>
                    <td>{row.sales.toLocaleString()}</td>
                    <td>{row.target.toLocaleString()}</td>
                    <td>{rate}%</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}
